/*
 * Scotiabank footer interactions, bound on existing footer markup (AEM footer component of the
 * footer Experience Fragment, or the fallback built by blocks/footer). Self-contained: also
 * shipped in the AEM clientlib (aem-scotia clientlib-site js/footer.js, generated by
 * tools/sync-from-eds.mjs).
 */

/**
 * @param {Element} footer the footer markup root (.footer-inner)
 */
export default function initFooter(footer) {
  if (!footer || footer.dataset.footerInit) return;
  footer.dataset.footerInit = 'true';
  // "Cookie Settings" opens the OneTrust preference centre, as on prod
  footer.querySelectorAll('.footer-cookie-settings').forEach((button) => {
    button.addEventListener('click', () => window.OneTrust?.ToggleInfoDisplay?.());
  });
}
